  \lean{ProbabilityTheory.fDiv_eq_zero_iff'}
  \leanok
  \uses{def:fDiv}
  Let $\mu, \nu$ be two probability measures. Assume $f'(\infty) = + \infty$ and $f(1) = 0$. Then $D_f(\mu, \nu) = 0$ if and only if $\mu = \nu$.
\end{lemma}

n17944.content:
\begin{proof}\leanok
