n18018.content:
\begin{theorem}
  \label{thm:fDiv_map_le}
  \lean{ProbabilityTheory.fDiv_map_le}
  \leanok
  \uses{def:fDiv}
  Let $\mu, \nu \in \mathcal M (\mathcal X)$ be two finite measures and let $g : \mathcal X \to \mathcal Y$ be a measurable function. Then
  $D_f(g_* \mu, g_* \nu) \le D_f(\mu, \nu)$.
\end{theorem}

n18019.content:
\begin{proof}\leanok
\uses{lem:DPI_of_DPI_ac,lem:rnDeriv_map_eq_condexp,thm:condexp_jensen}
By Lemma~\ref{lem:DPI_of_DPI_ac}, it is sufficient to prove the inequality with the additional hypothesis $\mu \ll \nu$ (hence also $g_* \mu \ll g_*\nu$). In that case,
\begin{align*}
D_f(g_* \mu, g_* \nu)
&= \int_y f \left( \frac{d g_* \mu}{d g_* \nu}(y) \right) \partial(g_* \nu)
\\
&= \int_{x} f \left( \frac{d g_* \mu}{d g_* \nu}(g(x)) \right) \partial\nu
\: .
\end{align*}
By Lemma~\ref{lem:rnDeriv_map_eq_condexp}, $\nu$-almost everywhere,
\begin{align*}
\frac{d g_* \mu}{d g_* \nu}(g(x))
&= \nu\left[\frac{d \mu}{d \nu} \mid g^* \mathcal Y \right](x)
\: .
\end{align*}
Using that expression, then Jensen's inequality for the conditional expectation(Theorem~\ref{thm:condexp_jensen}), we get
\begin{align*}
D_f(g_* \mu, g_* \nu)
&= \int_{x} f \left( \nu\left[\frac{d \mu}{d \nu} \mid g^* \mathcal Y \right](x) \right) \partial\nu
\\
&\le \int_{x} \nu\left[ f \left( \frac{d \mu}{d \nu} \right) \mid g^* \mathcal Y \right](x) \partial\nu
\: .
\end{align*}
The integral of a conditional expectation is equal to the integral of the function, hence
\begin{align*}
D_f(\kappa \circ \mu, \kappa \circ \nu)
&\le \int_{x} f \left( \frac{d \mu}{d \nu}(x) \right) \partial\nu
\: .
\end{align*}
This is equal to $D_f(\mu, \nu)$.
\end{proof}

