  \uses{def:KL, def:condKL}
  Let $\mu, \nu$ be two finite measures on $\mathcal X \times \mathcal Y$, where $\mathcal Y$ is standard Borel.
  Then $\KL(\mu, \nu) = \KL(\mu_X, \nu_X) + \KL(\mu_{Y|X}, \nu_{Y|X} \mid \mu_X)$.
\end{theorem}

