n18218.content:
\begin{definition}[Chernoff divergence]
  \label{def:Chernoff}
  \lean{ProbabilityTheory.chernoffDiv}
  \leanok
  \uses{def:Renyi, lem:renyi_properties}
    The Chernoff divergence of order $\alpha > 0$ between two measures $\mu$ and $\nu$ on $\mathcal X$ is
  \begin{align*}
    C_\alpha(\mu, \nu) = \inf_{\xi \in \mathcal P(\mathcal X)}\max\{R_\alpha(\xi, \mu), R_\alpha(\xi, \nu)\} \: .
  \end{align*}
\end{definition}

n18227.content:
\begin{definition}[Jensen-Shannon divergence]
  \label{def:jensenShannon}
  %\lean{}
  %\leanok
  \uses{def:KL, lem:kl_properties}
  The Jensen-Shannon divergence indexed by $\alpha \in (0,1)$ between two measures $\mu$ and $\nu$ is
  \begin{align*}
    \JS_\alpha(\mu, \nu) = \alpha \KL(\mu, \alpha \mu + (1 - \alpha)\nu) + (1 - \alpha) \KL(\nu, \alpha \mu + (1 - \alpha)\nu) \: .
  \end{align*}
\end{definition}

n18228.content:
\begin{lemma}
  \label{lem:jensenShannon_eq_kl}
  %\lean{}
  %\leanok
  \uses{def:jensenShannon, def:KL}
  Let $\mu, \nu \in \mathcal P(\mathcal X)$ and let $\alpha \in (0, 1)$. Let $\pi_\alpha = (\alpha, 1 - \alpha) \in \mathcal P(\{0,1\})$ and let $P : \{0,1\} \rightsquigarrow \mathcal X$ be the kernel with $P(0) = \mu$ and $P(1) = \nu$. Then
  \begin{align*}
  \JS_\alpha(\mu, \nu) = \KL(\pi_\alpha \otimes P, \pi_\alpha \times (P \circ \pi_\alpha)) \: .
  \end{align*}
\end{lemma}

n18230.content:
\begin{lemma}
  \label{lem:jensenShannon_eq_fDiv}
  %\lean{}
  %\leanok
  \uses{def:jensenShannon, def:KL}
  $\JS_\alpha$ is an $f$-divergence for $f(x) = \alpha x \log(x) - (\alpha x + 1 - \alpha) \log (\alpha x + 1 - \alpha)$~.
\end{lemma}

n18231.content:
\begin{proof}%\leanok
\uses{lem:fDiv_add_smul_right, lem:fDiv_add_smul_right', lem:fDiv_add, lem:fDiv_mul, lem:fDiv_properties}
$(\mu, \nu) \mapsto \KL(\mu, \alpha \mu + (1 - \alpha) \nu)$ is an $f$-divergence for the function $x \mapsto x\log\left(\frac{x}{\alpha x + 1 - \alpha}\right)$ (Lemma~\ref{lem:fDiv_add_smul_right}).

$(\mu, \nu) \mapsto \KL(\nu, \alpha \mu + (1 - \alpha) \nu)$ is an $f$-divergence for the function $x \mapsto x\log\left(\frac{1}{\alpha x + 1 - \alpha}\right)$ (Lemma~\ref{lem:fDiv_add_smul_right'}).

By Lemmas~\ref{lem:fDiv_mul} and \ref{lem:fDiv_add}, we obtain the result.
\end{proof}

n18234.content:
\begin{lemma}
  \label{lem:jensenShannon_eq_inf_add_kl}
  %\lean{}
  %\leanok
  \uses{def:jensenShannon, def:KL}
  Let $\mu, \nu \in \mathcal P(\mathcal X)$ and let $\alpha \in (0, 1)$. Then
  \begin{align*}
  \JS_\alpha(\mu, \nu) = \inf_{\xi \in \mathcal P(\mathcal X)}\left( \alpha \KL(\mu, \xi) + (1 - \alpha)\KL(\nu, \xi) \right) \: .
  \end{align*}
  The infimum is attained at $\xi = \alpha \mu + (1 - \alpha) \nu$.
\end{lemma}

n18236.content:
\begin{lemma}
  \label{lem:jensenShannon_eq_inf_kl}
  %\lean{}
  %\leanok
  \uses{def:jensenShannon, def:KL}
  Let $\mu, \nu \in \mathcal P(\mathcal X)$ and let $\alpha \in (0, 1)$. Let $\pi_\alpha = (\alpha, 1 - \alpha) \in \mathcal P(\{0,1\})$ and let $P : \{0,1\} \rightsquigarrow \mathcal X$ be the kernel with $P(0) = \mu$ and $P(1) = \nu$. Then
  \begin{align*}
  \JS_\alpha(\mu, \nu) = \inf_{\xi \in \mathcal P(\mathcal X)} \KL\left( \pi_\alpha \otimes P, \pi_\alpha \times \xi \right) \: .
  \end{align*}
  The infimum is attained at $\xi = \alpha \mu + (1 - \alpha) \nu$.
\end{lemma}

n18238.content:
\begin{lemma}
  \label{lem:jensenShannon_prod_n}
  %\lean{}
  %\leanok
  \uses{def:jensenShannon}
  Let $\mu, \nu$ be two probability measures on $\mathcal X$. Let $n \in \mathbb{N}$ and write $\mu^{\otimes n}$ for the product measure on $\mathcal X^n$ of $n$ times $\mu$.
  Then $\JS_\alpha(\mu^{\otimes n}, \nu^{\otimes n}) \le n \JS_\alpha(\mu, \nu)$.
\end{lemma}

n18240.content:
\begin{lemma}
  \label{lem:jensenShannon_le_hellingerAlpha}
  %\lean{}
  %\leanok
  \uses{def:jensenShannon, def:hellingerAlpha}
  For $\mu, \nu \in \mathcal P(\mathcal X)$ and $\alpha, \lambda \in (0,1)$~,
  \begin{align*}
  \JS_\alpha(\mu, \nu) \le \frac{(1 - \alpha)^{1 - \lambda} \alpha^\lambda}{\lambda^{1 - \lambda} (1 - \lambda)^\lambda} (1 - \lambda)\He_\lambda(\mu, \nu) \: .
  \end{align*}
  In particular,
  \begin{align*}
  \JS_\alpha(\mu, \nu)
  &\le \left(\frac{1 - \alpha}{\alpha}\right)^{1 - 2 \alpha} (1 - \alpha)\He_\alpha(\mu, \nu)
  \: , \\
  \JS_\alpha(\mu, \nu)
  &\le \alpha \He_{1 - \alpha}(\mu, \nu)
  \: .
  \end{align*}
\end{lemma}

n18241.content:
\begin{proof}%\leanok
\uses{lem:fDiv_le_of_deriv2_le, lem:jensenShannon_eq_fDiv}
The main tool is Lemma~\ref{lem:fDiv_le_of_deriv2_le}.
$\JS_\alpha$ is an $f$-divergence with function $f(x) = \alpha x \log(x) - (\alpha x + 1 - \alpha) \log (\alpha x + 1 - \alpha)$. On probability measures, $(1 - \lambda)\He_\lambda$ is an $f$-divergence with function $g(x) = 1 - x^\lambda + \lambda(x-1)$.
These two functions satisfy $f(1) = 0$, $g(1) = 0$, $f'(1) = 0$, $g'(1) = 0$ and have second derivatives, hence Lemma~\ref{lem:fDiv_le_of_deriv2_le} applies and to obtain the inequality it suffices to compute $\sup_x\frac{f''(x)}{g''(x)}$~.
\begin{align*}
f''(x)
&= \frac{\alpha(1 - \alpha)}{x(\alpha x + 1 - \alpha)}
\: , \\
g''(x)
&= \lambda (1 - \lambda) x^{\lambda - 2}
\: .
\end{align*}
Let $h(x) = \frac{f''(x)}{g''(x)} = \frac{\alpha (1 - \alpha)}{\lambda (1 - \lambda)} \frac{x^{1 - \lambda}}{\alpha x + 1 - \alpha}$~. Its maximum is attained at a point where $h'(x) = 0$.
\begin{align*}
h'(x) = \frac{\alpha (1 - \alpha)}{\lambda (1 - \lambda)} \frac{(1 - \alpha)(1 - \lambda)x^{-\lambda} - \alpha \lambda x^{1 - \lambda}}{(\alpha x + 1 - \alpha)^2}
\: .
\end{align*}
The optimum for $h$ is attained at $x = \frac{(1 - \alpha)(1 - \lambda)}{\alpha \lambda}$ and the maximal value of $h$ is $\frac{(1 - \alpha)^{1 - \lambda} \alpha^\lambda}{\lambda^{1 - \lambda} (1 - \lambda)^\lambda}$~.
\end{proof}

n18243.content:
\begin{proof}%\leanok
\uses{lem:jensenShannon_le_hellingerAlpha}
By Lemma~\ref{lem:jensenShannon_le_hellingerAlpha} for $\alpha$ and $1 - \lambda$,
\begin{align*}
\JS_\alpha(\mu, \nu)
&\le \frac{(1 - \alpha)^{\lambda} \alpha^{1 - \lambda}}{\lambda^{1 - \lambda} (1 - \lambda)^\lambda} \lambda \He_{1 - \lambda}(\mu, \nu)
\\
&= \alpha^{1 - \lambda} (1 - \alpha)^\lambda \left(\frac{\lambda}{1 - \lambda}\right)^\lambda \He_{1 - \lambda}(\mu, \nu)
\: .
\end{align*}
To get the result, use $1 - \alpha \le 1$ and $\frac{\lambda}{1 - \lambda} \le 1$ since it is increasing in $\lambda$ with value 1 at $\lambda = 1/2$.

\end{proof}

n18244.content:
\begin{definition}
  \label{def:mutualInfo}
  %\lean{}
  %\leanok
  \uses{def:KL, lem:kl_properties}
  The mutual information is, for $\rho \in \mathcal M(\mathcal X \times \mathcal Y)$~,
  \begin{align*}
  I(\rho) = \KL(\rho, \rho_X \times \rho_Y) \: .
  \end{align*}
\end{definition}

n18245.content:
\begin{definition}
  \label{def:condMutualInfo}
  %\lean{}
  %\leanok
  \uses{def:condKL, lem:kl_properties}
  Let $\kappa : \mathcal Z \rightsquigarrow \mathcal X \times \mathcal Y$. The conditional mutual information of $\kappa$ with respect to $\nu \in \mathcal M(\mathcal Z)$ is
  \begin{align*}
  I(\kappa \mid \nu) = \KL(\kappa, \kappa_X \times \kappa_Y \mid \nu) \: .
  \end{align*}
\end{definition}

n18246.content:
\begin{lemma}
  \label{lem:mutualInfo_eq_condKL}
  %\lean{}
  %\leanok
  \uses{def:mutualInfo, def:KL, def:condKL}
  For $\mu \in \mathcal M(\mathcal X)$ and $\kappa : \mathcal X \rightsquigarrow \mathcal Y$ a Markov kernel,
  \begin{align*}
  I(\mu \otimes \kappa)
  = KL(\mu \otimes \kappa, \mu \times (\kappa \circ \mu))
  = KL(\kappa, \kappa \circ \mu \mid \mu)
  \: ,
  \end{align*}
  where in the conditional divergence the measure $\kappa \circ \mu$ should be understood as the constant kernel from $\mathcal X$ to $\mathcal Y$ with that value.
\end{lemma}

n18247.content:
\begin{proof}%\leanok
\uses{}
The first equality is the definition of $I$, together with $(\mu \otimes \kappa)_X = \mu$ (since $\kappa$ is Markov) and $(\mu \otimes \kappa)_Y = \kappa \circ \mu$.
The second equality is from $KL(\kappa, \eta \mid \mu) = KL(\mu \otimes \kappa, \mu \otimes \eta)$. (TODO: now from a lemma, soon by definition).
\end{proof}

n18250.content:
\begin{lemma}
  \label{lem:mutualInfo_eq_jensenShannon}
  %\lean{}
  %\leanok
  \uses{def:mutualInfo, def:jensenShannon}
  Let $\mu, \nu \in \mathcal P(\mathcal X)$ and let $\alpha \in (0, 1)$. Let $\pi_\alpha = (\alpha, 1 - \alpha) \in \mathcal P(\{0,1\})$ and let $P : \{0,1\} \rightsquigarrow \mathcal X$ be the kernel with $P(0) = \mu$ and $P(1) = \nu$. Then
  \begin{align*}
  I(\pi_\alpha \otimes P) = \JS_\alpha(\mu, \nu) \: .
  \end{align*}
\end{lemma}

n18252.content:
\begin{theorem}[Data-processing]
  \label{thm:mutualInfo_data_proc}
  %\lean{}
  %\leanok
  \uses{def:mutualInfo}
  For $\rho \in \mathcal M(\mathcal X \times \mathcal Y)$, $\kappa : \mathcal X \rightsquigarrow \mathcal X'$ and $\eta : \mathcal Y \rightsquigarrow \mathcal Y'$ two Markov kernels,
  \begin{align*}
  I((\kappa \parallel \eta) \circ \rho) \le I(\rho) \: .
  \end{align*}
\end{theorem}

n18253.content:
\begin{proof}%\leanok
\uses{thm:kl_data_proc}
$((\kappa \parallel \eta) \circ \rho)_{X'} = \kappa \circ \rho_X$ and $((\kappa \parallel \eta) \circ \rho)_{Y'} = \eta \circ \rho_Y$ hence
\begin{align*}
((\kappa \parallel \eta) \circ \rho)_{X'} \times ((\kappa \parallel \eta) \circ \rho)_{Y'}
&= (\kappa \circ \rho_X) \times (\eta \circ \rho_Y)
= (\kappa \parallel \eta) \circ (\rho_X \times \rho_Y)
\: .
\end{align*}

By the data-processing inequality for $\KL$ (Theorem~\ref{thm:kl_data_proc}),
\begin{align*}
I((\kappa \parallel \eta) \circ \rho)
&= \KL((\kappa \parallel \eta) \circ \rho, (\kappa \parallel \eta) \circ (\rho_X \times \rho_Y))
\\
&\le \KL(\rho, \rho_X \times \rho_Y)
\\
&= I(\rho)
\: .
\end{align*}
\end{proof}

n18254.content:
\begin{corollary}
  \label{cor:mutualInfo_compProd_le}
  %\lean{}
  %\leanok
  \uses{def:mutualInfo}
  For $\mu \in \mathcal X$, $\kappa : \mathcal X \rightsquigarrow \mathcal Y$ and $\eta : \mathcal Y \rightsquigarrow \mathcal Z$ two Markov kernels,
  \begin{align*}
  I(\mu \otimes (\eta \circ \kappa)) \le I(\mu \otimes \kappa)
  \: .
  \end{align*}
\end{corollary}

n18256.content:
\begin{definition}
  \label{def:mutualInfoLeft}
  %\lean{}
  %\leanok
  \uses{def:fDiv, lem:fDiv_properties}
  Let $D$ be a divergence between measures.
  The left $D$-mutual information for a measure $\mu \in \mathcal M(\mathcal X)$ and a kernel $\kappa : \mathcal X \rightsquigarrow \mathcal Y$ is
  \begin{align*}
  I_D^L(\mu, \kappa) = \inf_{\xi \in \mathcal P(\mathcal Y)} D(\mu \times \xi, \mu \otimes \kappa) \: .
  \end{align*}
\end{definition}

n18257.content:
\begin{definition}
  \label{def:mutualInfoRight}
  %\lean{}
  %\leanok
  \uses{def:fDiv, lem:fDiv_properties}
  Let $D$ be a divergence between measures.
  The right $D$-mutual information for a measure $\mu \in \mathcal M(\mathcal X)$ and a kernel $\kappa : \mathcal X \rightsquigarrow \mathcal Y$ is
  \begin{align*}
  I_D^R(\mu, \kappa) = \inf_{\xi \in \mathcal P(\mathcal Y)} D(\mu \otimes \kappa, \mu \times \xi) \: .
  \end{align*}
\end{definition}

n18258.content:
\begin{lemma}
  \label{lem:mutualInfoLeft_eq_renyi}
  %\lean{}
  %\leanok
  \uses{def:mutualInfoLeft, def:Renyi}
  For $\mu \in \mathcal P(\{0,1\})$ and $\kappa : \{0,1\} \rightsquigarrow \mathcal Y$,
  \begin{align*}
  I_{\KL}^L(\mu, \kappa) = (1 - \mu_0) R_{\mu_0}(\kappa_0, \kappa_1) \: .
  \end{align*}
\end{lemma}

n18260.content:
\begin{lemma}
  \label{lem:mutualInfoRight_eq_mutualInfo}
  %\lean{}
  %\leanok
  \uses{def:mutualInfoRight, def:mutualInfo}
  For $\mu \in \mathcal P(\mathcal X)$ and $\kappa : \mathcal X \rightsquigarrow \mathcal Y$,
  \begin{align*}
  I_{\KL}^R(\mu, \kappa) = I(\mu \otimes \kappa) \: .
  \end{align*}
\end{lemma}

n18262.content:
\begin{corollary}
  \label{cor:mutualInfoRight_eq_jensenShannon}
  %\lean{}
  %\leanok
  \uses{def:mutualInfoRight, def:jensenShannon}
  For $\mu \in \mathcal P(\{0,1\})$ and $\kappa : \{0,1\} \rightsquigarrow \mathcal Y$,
  \begin{align*}
  I_{\KL}^R(\mu, \kappa) = \JS_{\mu_0}(\kappa_0, \kappa_1) \: .
  \end{align*}
\end{corollary}

n18264.content:
\begin{theorem}
  \label{thm:mutualInfoLeft_comp_le}
  %\lean{}
  %\leanok
  \uses{def:mutualInfoLeft, def:mutualInfoRight}
  If the divergence $D$ satisfies the data-processing inequality, then for all $\mu \in \mathcal M(\mathcal X)$, $\kappa : \mathcal X \rightsquigarrow \mathcal Y$ and all Markov kernels $\eta : \mathcal Y \rightsquigarrow \mathcal Z$ then
  \begin{align*}
  I_D^L(\mu, \eta \circ \kappa) \le I_D^L(\mu, \kappa)
  \: , \\
  I_D^R(\mu, \eta \circ \kappa) \le I_D^R(\mu, \kappa)
  \: .
  \end{align*}

\end{theorem}

n18266.content:
\begin{lemma}
  \label{lem:mutualInfoLeft_estimation_ge}
  %\lean{}
  %\leanok
  \uses{def:mutualInfoLeft, def:mutualInfoRight, def:bayesRisk}
  Let $\pi \in \mathcal P(\Theta)$ and $P : \Theta \rightsquigarrow \mathcal X$. Suppose that the loss $\ell'$ of an estimation task with kernel $P$ takes values in $[0,1]$. Then
  \begin{align*}
  I_{D_f}^L(\pi, P)
  &\ge d_f(\mathcal R_\pi^{d_\Theta}, \mathcal R_\pi^P)
  \: , \\
  I_{D_f}^R(\pi, P)
  &\ge d_f(\mathcal R_\pi^P, \mathcal R_\pi^{d_\Theta})
  \: .
  \end{align*}
\end{lemma}

n18267.content:
\begin{proof}%\leanok
\uses{lem:fDiv_estimation_ge}
The left mutual information $I_D^L(\pi, P)$ is an infimum: $I_D^L(\pi, P) = \inf_{\xi \in \mathcal P(\mathcal X)} D(\pi \times \xi, \pi \otimes P)$.
For all $\xi \in \mathcal P(\mathcal X)$, by Lemma~\ref{lem:fDiv_estimation_ge},
\begin{align*}
D_f(\pi \times \xi, \pi \otimes P) &\ge d_f(\mathcal R_\pi^{\theta \mapsto \xi}, \mathcal R_\pi^P) \: .
\end{align*}
The risk of a constant Markov kernel is equal to the risk of the discard kernel $d_\Theta$ (TODO ref).

The proof for the right mutual information is similar.
\end{proof}

n18268.content:
\begin{lemma}[\cite{zhou2018non}]
  \label{lem:bayesBinaryRisk_eq_exp_renyi_mul_integral}
  %\lean{}
  %\leanok
  \uses{def:bayesBinaryRisk, def:Renyi, def:renyiMeasure}
  Let $\zeta$ be a measure such that $\mu \ll \zeta$ and $\nu \ll \zeta$. Let $p = \frac{d \mu}{d\zeta}$ and $q = \frac{d \nu}{d\zeta}$.
  For $\alpha \in (0,1)$, for $g_\alpha(x) = \min\{(\alpha-1)x, \alpha x\}$,
  \begin{align*}
  \mathcal B_\xi(\mu, \nu)
  = e^{-(1 - \alpha) R_\alpha(\xi_0\mu, \xi_1\nu)} \int_x \exp \left(g_\alpha\left( \log \frac{\xi_1 q(x)}{\xi_0 p(x)} \right)\right) \partial(\xi_0\mu)^{(\alpha, \xi_1\nu)}
  \: .
  \end{align*}
\end{lemma}

n18269.content:
\begin{proof}%\leanok
\uses{thm:bayesBinaryRisk_eq}
\begin{align*}
\mathcal B_\xi(\mu, \nu)
&= \int_x \min \left\{\xi_0 p(x), \xi_1 q(x)\right\} \partial\zeta
\\
&= \int_x (\xi_0 p(x))^\alpha (\xi_1 q(x))^{1-\alpha} \min \left\{ \left(\frac{\xi_0p(x)}{\xi_1q(x)}\right)^{1 - \alpha}, \left(\frac{\xi_1q(x)}{\xi_0p(x)}\right)^\alpha\right\} \partial\zeta
\\
&= e^{-(1 - \alpha) R_\alpha(\xi_0\mu, \xi_1\nu)} \int_x \min \left\{ \left(\frac{\xi_1q(x)}{\xi_0p(x)}\right)^{\alpha - 1}, \left(\frac{\xi_1q(x)}{\xi_0p(x)}\right)^\alpha\right\} \partial(\xi_0\mu)^{(\alpha, \xi_1\nu)}
\: .
\end{align*}
\end{proof}

n18270.content:
\begin{corollary}
  \label{cor:bayesBinaryRisk_le_exp_renyi}
  %\lean{}
  %\leanok
  \uses{def:bayesBinaryRisk, def:Renyi}
  For $\alpha \in (0,1)$,
  \begin{align*}
  \mathcal B_\xi(\mu, \nu)
  \le e^{-(1 - \alpha) R_\alpha(\xi_0\mu, \xi_1\nu)}
  = \xi_0^\alpha \xi_1^{1-\alpha} e^{-(1 - \alpha) R_\alpha(\mu, \nu)}
  \: .
  \end{align*}
\end{corollary}

n18273.content:
\begin{proof}%\leanok
\uses{cor:bayesBinaryRisk_le_exp_renyi, lem:chernoff_eq_max_renyi}
Optimize over $\alpha$ in Corollary~\ref{cor:bayesBinaryRisk_le_exp_renyi}: the optimal value gives the Chernoff information thanks to Lemma~\ref{lem:chernoff_eq_max_renyi}.
\end{proof}

n18274.content:
\begin{lemma}
  \label{lem:one_sub_tv_le_exp_chernoff}
  %\lean{}
  %\leanok
  \uses{def:TV, def:Chernoff}
  For probability measures,
  \begin{align*}
  1 - \TV(\mu, \nu) \le e^{- C_1(\mu, \nu)} \: .
  \end{align*}
\end{lemma}

n18275.content:
\begin{proof}%\leanok
\uses{lem:bayesBinaryRisk_le_exp_chernoff}
By definition, since $\mu$ and $\nu$ are probability measures, $1 - \TV(\mu, \nu) = \mathcal B_{(1,1)}(\mu, \nu)$. Then apply Lemma~\ref{lem:bayesBinaryRisk_le_exp_chernoff}.
\end{proof}

n18276.content:
\begin{lemma}
  \label{lem:kl_estimation_ge}
  %\lean{}
  %\leanok
  \uses{def:KL, def:bayesRisk}
  Let $\pi, \xi \in \mathcal P(\Theta)$ and $P, Q : \Theta \rightsquigarrow \mathcal X$. Suppose that the loss $\ell'$ takes values in $[0,1]$. Then
  \begin{align*}
  \KL(\pi \otimes Q, \xi \otimes P)
  &\ge \kl(\mathcal R_\pi^Q, \mathcal R_\xi^P)
  \: .
  \end{align*}
\end{lemma}

n18277.content:
\begin{proof}%\leanok
\uses{lem:fDiv_estimation_ge}
This is Lemma~\ref{lem:fDiv_estimation_ge} specialized to the Kullback-Leibler divergence.
\end{proof}

n18278.content:
\begin{corollary}
  \label{cor:kl_estimation_ge_sub_kl'}
  %\lean{}
  %\leanok
  \uses{def:KL, def:bayesRisk}
  Let $\pi, \xi \in \mathcal P(\Theta)$ and $P, Q : \Theta \rightsquigarrow \mathcal X$. Suppose that the loss $\ell'$ takes values in $[0,1]$. Then
  \begin{align*}
  \KL(\pi \otimes Q, \pi \otimes P)
  &\ge \kl(\mathcal R_\pi^Q, \mathcal R_\xi^P) - \KL(\pi, \xi)
  \: .
  \end{align*}
\end{corollary}

n18279.content:
